/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       clk,
    input  logic       reset,
    output logic [4:0] q
);
    always_ff @(posedge clk) begin
        if (reset)
            q <= 5'b00001;
        else
            q <= {q[0], q[4], q[3] "'^ q[0], q[2], q[1]};
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
'

